(()=>{if(!document.body.dataset.page||window.__lazyHelper)return;window.__lazyHelper=true;const loaded=new Set();let running=false;const button=document.createElement('button');button.className='lazy-franklin';button.textContent='Ask Franklin';button.setAttribute('aria-label','Connect to Franklin');(document.querySelector('#feedback-helper-slot')||document.body).append(button);const panel=document.createElement('section');panel.className='asset-loader';panel.hidden=true;panel.setAttribute('role','dialog');panel.setAttribute('aria-label','Loading Franklin');panel.innerHTML='<div><small>ASSISTANT CHANNEL</small><h2>Connecting to Franklin</h2><p role="status">Building the interface…</p><progress max="100" value="0" aria-label="Assets loaded"></progress><small class="asset-count"></small><button type="button">Close</button></div>';document.body.append(panel);panel.querySelector('button').onclick=()=>{panel.hidden=true};
const scripts=['franklin-conversation.js','ask-franklin.js','franklin-analytics.js','franklin-moderation.js','franklin-funding.js','franklin-typing.js','franklin-support-context.js','franklin-developer-kb.js','franklin-log-files.js','franklin-dataset-engine.js','franklin-site-rag.js','franklin-webllm.js','franklin-engine-extra.js','franklin-engine.js'];
function script(src){if(loaded.has(src))return Promise.resolve();return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src+'?v=20261028lazy';const timeout=setTimeout(()=>{s.remove();reject(Error('Connection timed out. Tap Retry.'))},20000);s.onload=()=>{clearTimeout(timeout);loaded.add(src);resolve()};s.onerror=()=>{clearTimeout(timeout);s.remove();reject(Error('An asset could not load. Check your connection and retry.'))};document.head.append(s)})}
button.onclick=async()=>{panel.hidden=false;if(running)return;running=true;button.disabled=true;const status=panel.querySelector('p'),progress=panel.querySelector('progress'),count=panel.querySelector('.asset-count');let done=0;const total=scripts.length+2;const update=()=>{progress.value=100*done/total;count.textContent=done+' / '+total+' assets ready'};try{update();for(const src of scripts){status.textContent=done<2?'Building the interface…':'Assembling assistant assets…';await script(src);done++;update()}status.textContent='Loading project knowledge…';for(const api of [window.FranklinDeveloperKB,window.FranklinDataset]){const data=await Promise.race([api.load(),new Promise((_,reject)=>setTimeout(()=>reject(Error('Knowledge timed out. Reload the page to retry.')),20000))]);if(!data?.length)throw Error('Knowledge could not load. Reload the page to retry.');done++;update()}await Promise.all([...document.querySelectorAll('link[data-ask-franklin]')].map(link=>link.sheet?Promise.resolve():new Promise((resolve,reject)=>{link.addEventListener('load',resolve,{once:true});link.addEventListener('error',()=>reject(Error('Interface styles could not load. Reload to retry.')),{once:true});setTimeout(()=>link.sheet?resolve():reject(Error('Styles timed out. Reload to retry.')),20000)})));status.textContent='Ready';button.remove();const launcher=document.querySelector('.ask-franklin-launcher');if(!panel.hidden&&launcher){if(launcher.dataset.state==='compact')launcher.click();launcher.click()}panel.hidden=true;document.body.classList.remove('helper-assets-pending')}catch(e){status.textContent=e.message||'Unable to connect. Please retry.';button.textContent='Retry Franklin';button.disabled=false}finally{running=false}};document.body.classList.add('helper-assets-pending');})();
